"<g0>Prenájom ⟨M1⟩</g0> začína na {1} € mesačne, s limitom {2}–{3} km/mes. a dobou prenájmu {4} mesiacov. Jednorazová vratná <g1>kaucia</g1> začína na {5} €. Presná cena závisí od verzie, farby a balíka výbavy — mesačnú splátku a dostupnosť každého modelu nájdete medzi našimi <g2>autami na prenájom</g2>.": [
"<g0>⟨M1⟩ rental</g0> starts at {1} € per month, with a limit of {2}–{3} km/month and a rental period of {4} months. The one-off refundable <g1>deposit</g1> starts at {5} €. The exact price depends on the version, colour and equipment package — you will find the monthly payment and availability of each model among our <g2>cars for rent</g2>.",
"<g0>Die Miete eines ⟨M1⟩</g0> beginnt bei {1} € pro Monat, mit einem Limit von {2}–{3} km/Monat und einer Mietdauer von {4} Monaten. Die einmalige rückzahlbare <g1>Kaution</g1> beginnt bei {5} €. Der genaue Preis hängt von Version, Farbe und Ausstattungspaket ab — Monatsrate und Verfügbarkeit jedes Modells finden Sie bei unseren <g2>Mietwagen</g2>.",
"<g0>A ⟨M1⟩ bérlése</g0> havi {1} €-tól indul, {2}–{3} km/hó futáskerettel és {4} hónapos bérleti idővel. Az egyszeri, visszajáró <g1>kaució</g1> {5} €-tól indul. A pontos ár a változattól, a színtől és a felszereltségi csomagtól függ — minden modell havidíját és elérhetőségét megtalálod <g2>bérelhető autóink</g2> között."
],
