"<g0>Prenájom ⟨M1⟩</g0> je najjednoduchšia cesta k úplne novému autu: v <g1>dlhodobom prenájme</g1> ho môžete jazdiť od {1} €/mes., s limitom {2}–{3} km/mes. a dobou prenájmu {4} mesiacov. Momentálne si môžete vybrať z {5} áut ⟨M2⟩ ({6} k dispozícii ihneď). Jednorazová vratná <g2>kaucia</g2> od {7} €; servis, daň a letné aj zimné pneumatiky hradíme my. Auto nemusíte vlastniť: na konci prenájmu ho jednoducho vrátite alebo prejdete na nový model.": [
"<g0>Renting the ⟨M1⟩</g0> is the easiest way to a brand-new car: on <g1>long-term rental</g1> you can drive it from {1} €/month, with a limit of {2}–{3} km/month and a rental period of {4} months. You can currently choose from {5} ⟨M2⟩ cars ({6} available immediately). One-off refundable <g2>deposit</g2> from {7} €; we pay for servicing, tax and summer and winter tyres. You don't have to own the car: at the end of the rental you simply return it or switch to a new model.",
"<g0>Die Miete eines ⟨M1⟩</g0> ist der einfachste Weg zu einem brandneuen Auto: in der <g1>Langzeitmiete</g1> fahren Sie ihn ab {1} €/Monat, mit einem Limit von {2}–{3} km/Monat und einer Mietdauer von {4} Monaten. Derzeit stehen {5} ⟨M2⟩ zur Auswahl ({6} sofort verfügbar). Einmalige rückzahlbare <g2>Kaution</g2> ab {7} €; Service, Steuer sowie Sommer- und Winterreifen übernehmen wir. Sie müssen das Auto nicht besitzen: Am Ende der Miete geben Sie es einfach zurück oder wechseln auf ein neues Modell.",
"<g0>A ⟨M1⟩ bérlése</g0> a legegyszerűbb út egy vadonatúj autóhoz: <g1>tartós bérletben</g1> {1} €/hó-tól vezetheted, {2}–{3} km/hó futáskerettel és {4} hónapos bérleti idővel. Jelenleg {5} ⟨M2⟩ közül választhatsz ({6} azonnal elérhető). Egyszeri, visszajáró <g2>kaució</g2> {7} €-tól; a szervizt, az adót, valamint a nyári és téli gumit mi fizetjük. Nem kell birtokolnod az autót: a bérlet végén egyszerűen visszaadod, vagy új modellre váltasz."
],
