"Prenájom ⟨M1⟩ a dlhodobý prenájom od {2} €/mes., {3}–{4} km/mes., na {5} mesiacov, kaucia od {6} €. Úplne nové, {7} km, kompakt.": [
"⟨M1⟩ rental and long-term rental from {2} €/month, {3}–{4} km/month, for {5} months, deposit from {6} €. Brand new, {7} km, compact.",
"⟨M1⟩ Miete und Langzeitmiete ab {2} €/Monat, {3}–{4} km/Monat, für {5} Monate, Kaution ab {6} €. Brandneu, {7} km, Kompaktklasse.",
"⟨M1⟩ bérlés és tartós bérlet {2} €/hó-tól, {3}–{4} km/hó, {5} hónapra, kaució {6} €-tól. Vadonatúj, {7} km, kompakt."
],
"<g0>Prenájom ⟨M1⟩</g0> je najjednoduchšia cesta k úplne novému autu: v <g1>dlhodobom prenájme</g1> ho môžete jazdiť od {2} €/mes., s limitom {3}–{4} km/mes. a dobou prenájmu {5} mesiacov. Momentálne si môžete vybrať z {6} áut ⟨M2⟩. Jednorazová vratná <g2>kaucia</g2> od {8} €; servis, daň a letné aj zimné pneumatiky hradíme my. Auto nemusíte vlastniť: na konci prenájmu ho jednoducho vrátite alebo prejdete na nový model.": [
"<g0>Renting the ⟨M1⟩</g0> is the easiest way to a brand-new car: on <g1>long-term rental</g1> you can drive it from {2} €/month, with a limit of {3}–{4} km/month and a rental period of {5} months. You can currently choose from {6} ⟨M2⟩ cars. One-off refundable <g2>deposit</g2> from {8} €; we pay for servicing, tax and summer and winter tyres. You don't have to own the car: at the end of the rental you simply return it or switch to a new model.",
"<g0>Die Miete eines ⟨M1⟩</g0> ist der einfachste Weg zu einem brandneuen Auto: in der <g1>Langzeitmiete</g1> fahren Sie ihn ab {2} €/Monat, mit einem Limit von {3}–{4} km/Monat und einer Mietdauer von {5} Monaten. Derzeit stehen {6} ⟨M2⟩ zur Auswahl. Einmalige rückzahlbare <g2>Kaution</g2> ab {8} €; Service, Steuer sowie Sommer- und Winterreifen übernehmen wir. Sie müssen das Auto nicht besitzen: Am Ende der Miete geben Sie es einfach zurück oder wechseln auf ein neues Modell.",
"<g0>A ⟨M1⟩ bérlése</g0> a legegyszerűbb út egy vadonatúj autóhoz: <g1>tartós bérletben</g1> {2} €/hó-tól vezetheted, {3}–{4} km/hó futáskerettel és {5} hónapos bérleti idővel. Jelenleg {6} db ⟨M2⟩ közül választhatsz. Egyszeri, visszajáró <g2>kaució</g2> {8} €-tól; a szervizt, az adót, valamint a nyári és téli gumit mi fizetjük. Nem kell birtokolnod az autót: a bérlet végén egyszerűen visszaadod, vagy új modellre váltasz."
],
