"<g0>Renting the ⟨M1⟩</g0> is the easiest way to a brand-new car: on <g1>long-term rental</g1> you can drive it from {1} €/month, with a limit of {2}–{3} km/month and a rental period of {4} months. You can currently choose from {5} ⟨M2⟩ cars. One-off refundable <g2>deposit</g2> from {6} €; we pay for servicing, tax and summer and winter tyres. You don't have to own the car: at the end of the rental you simply return it or switch to a new model.",
