"<g0>Model a karoséria</g0> — vyberte model; nižšie nájdete celú ponuku ⟨M1⟩ s nemeckými základnými cenami.": [
"<g0>Model and body</g0> — choose the model; below you will find the full ⟨M1⟩ range with German base prices.",
"<g0>Modell und Karosserie</g0> — wählen Sie das Modell; unten finden Sie das gesamte ⟨M1⟩ Angebot mit deutschen Grundpreisen.",
"<g0>Modell és karosszéria</g0> — válaszd ki a modellt; lent megtalálod a teljes ⟨M1⟩ kínálatot német alapárakkal."
],
"<g0>Pohon</g0> — benzín, diesel, plug-in hybrid alebo elektrina. Elektromobil má na Slovensku nižší registračný poplatok a nevzťahuje sa naň daň z motorových vozidiel.": [
"<g0>Drive</g0> — petrol, diesel, plug-in hybrid or electric. An electric car has a lower registration fee in Slovakia and is not subject to motor vehicle tax.",
"<g0>Antrieb</g0> — Benzin, Diesel, Plug-in-Hybrid oder Elektro. Ein Elektroauto hat in der Slowakei eine niedrigere Zulassungsgebühr und unterliegt nicht der Kfz-Steuer.",
"<g0>Hajtás</g0> — benzines, dízel, plug-in hibrid vagy elektromos. Az elektromos autó regisztrációs díja Szlovákiában alacsonyabb, és nem vonatkozik rá gépjárműadó."
],
"<g0>Farba, čalúnenie, disky</g0> — neutrálne metalízy sú na trhu ojazdených áut najžiadanejšie.": [
"<g0>Colour, upholstery, wheels</g0> — neutral metallic colours are the most sought-after on the used car market.",
"<g0>Farbe, Polsterung, Felgen</g0> — neutrale Metallicfarben sind auf dem Gebrauchtwagenmarkt am gefragtesten.",
"<g0>Szín, kárpit, felni</g0> — a semleges metálfényezések a legkeresettebbek a használtautó-piacon."
],
"<g0>Balíky a doplnky</g0> — v balíku je to zvyčajne lacnejšie ako jednotlivo.": [
"<g0>Packages and extras</g0> — in a package it is usually cheaper than individually.",
"<g0>Pakete und Extras</g0> — im Paket ist es meist günstiger als einzeln.",
"<g0>Csomagok és extrák</g0> — csomagban általában olcsóbb, mint egyenként."
],
"<g0>Uloženie</g0> — uložte konfiguráciu (odkaz, kód alebo PDF) a pošlite nám ju: pripravíme na ňu ponuku.": [
"<g0>Saving</g0> — save the configuration (link, code or PDF) and send it to us: we will prepare an offer for it.",
"<g0>Speichern</g0> — speichern Sie die Konfiguration (Link, Code oder PDF) und senden Sie sie uns: Wir erstellen ein Angebot dafür.",
"<g0>Mentés</g0> — mentsd el a konfigurációt (link, kód vagy PDF), és küldd el nekünk: ajánlatot készítünk rá."
],
