"Konfigurátor ⟨M1⟩: ako si poskladať nový ⟨M2⟩, ktoré balíky sa oplatia, a kompletný cenník modelov ⟨M3⟩ s nemeckými cenami bez DPH.": [
"⟨M1⟩ configurator: how to build a new ⟨M2⟩, which packages are worth it, and the complete ⟨M3⟩ model price list with German prices excl. VAT.",
"⟨M1⟩ Konfigurator: wie Sie einen neuen ⟨M2⟩ zusammenstellen, welche Pakete sich lohnen, und die komplette ⟨M3⟩ Modellpreisliste mit deutschen Preisen ohne MwSt.",
"⟨M1⟩ konfigurátor: hogyan állítsd össze az új ⟨M2⟩-t, melyik csomag éri meg, valamint a ⟨M3⟩ modellek teljes árlistája német, áfa nélküli árakkal."
],
"Konfigurátor ⟨M1⟩: ako si poskladať nové ⟨M2⟩, ktoré balíky sa oplatia, a kompletný cenník modelov ⟨M3⟩ s nemeckými cenami bez DPH.": [
"⟨M1⟩ configurator: how to build a new ⟨M2⟩, which packages are worth it, and the complete ⟨M3⟩ model price list with German prices excl. VAT.",
"⟨M1⟩ Konfigurator: wie Sie einen neuen ⟨M2⟩ zusammenstellen, welche Pakete sich lohnen, und die komplette ⟨M3⟩ Modellpreisliste mit deutschen Preisen ohne MwSt.",
"⟨M1⟩ konfigurátor: hogyan állítsd össze az új ⟨M2⟩-t, melyik csomag éri meg, valamint a ⟨M3⟩ modellek teljes árlistája német, áfa nélküli árakkal."
],
"Spojte sa s tímom CarAdvance. Vyberte si na mape svoj región a ukážeme vám, kto je váš osobný kontakt. Kancelária: Cesta na Senec {1}/A, {2} Bratislava.": [
"Get in touch with the CarAdvance team. Choose your region on the map and we will show you who your personal contact is. Office: Cesta na Senec {1}/A, {2} Bratislava.",
"Nehmen Sie Kontakt mit dem CarAdvance-Team auf. Wählen Sie auf der Karte Ihre Region, und wir zeigen Ihnen Ihren persönlichen Ansprechpartner. Büro: Cesta na Senec {1}/A, {2} Bratislava.",
"Vedd fel a kapcsolatot a CarAdvance csapatával. Válaszd ki a térképen a régiódat, és megmutatjuk, ki a személyes kapcsolattartód. Iroda: Cesta na Senec {1}/A, {2} Pozsony."
],
"Spoľahlivý autopredajca s nemeckým zázemím": [
"A reliable car dealer with a German background",
"Ein zuverlässiger Autohändler mit deutschem Hintergrund",
"Megbízható autókereskedő német háttérrel"
],
"{1}-ročná zodpovednosť za vady — ručíme za každé auto": [
"{1}-year liability for defects — we stand behind every car",
"{1} Jahr Sachmängelhaftung — wir stehen für jedes Auto ein",
"{1} év szavatosság — minden autóért felelünk"
],
"Transparentná cena, vopred pevne stanovená": [
"Transparent price, fixed in advance",
"Transparenter Preis, im Voraus festgelegt",
"Átlátható, előre rögzített ár"
],
"Referencie — skutočné recenzie, prenajaté, predané": [
"References — real reviews, rented, sold",
"Referenzen — echte Bewertungen, vermietet, verkauft",
"Referenciák — valódi vélemények, bérelt, eladott autók"
],
"Referencie CarAdvance: skutočné recenzie na Google, prenajaté, predané a z Nemecka dovezené prémiové autá na jednom mieste.": [
"CarAdvance references: real Google reviews, rented, sold and imported-from-Germany premium cars in one place.",
"CarAdvance Referenzen: echte Google-Bewertungen, vermietete, verkaufte und aus Deutschland importierte Premium-Autos an einem Ort.",
"CarAdvance referenciák: valódi Google-vélemények, bérelt, eladott és Németországból behozott prémium autók egy helyen."
],
"Transparentnosť — s kým uzatvárate zmluvu a čo platíte": [
"Transparency — who you sign the contract with and what you pay",
"Transparenz — mit wem Sie den Vertrag schließen und was Sie zahlen",
"Átláthatóság — kivel szerződsz, és mit fizetsz"
],
"Údaje o spoločnosti, zodpovednosti, zloženie mesačného poplatku za dlhodobý prenájom a kúpnej ceny, cesta kaucie a postup pri škode — prehľad transparentnosti CarAdvance.": [
"Company details, responsibilities, breakdown of the long-term rental monthly fee and the purchase price, the path of the deposit and the procedure in case of damage — the CarAdvance transparency overview.",
"Unternehmensdaten, Zuständigkeiten, Zusammensetzung der Monatsrate der Langzeitmiete und des Kaufpreises, der Weg der Kaution und das Vorgehen bei Schäden — die Transparenzübersicht von CarAdvance.",
"Cégadatok, felelősségi körök, a tartós bérlet havidíjának és a vételárnak az összetétele, a kaució útja és a kárügyintézés menete — a CarAdvance átláthatósági áttekintése."
],
"Preverená história, overené kilometre, kontrola na mieste, fotoprotokol pri odovzdaní a {1} rok zodpovednosti za vady — takto kontrolujeme dovezené, predávané aj prenajímané autá.": [
"Verified history, checked mileage, on-site inspection, photo report at handover and {1} year of liability for defects — this is how we check imported, sold and rented cars.",
"Geprüfte Historie, verifizierter Kilometerstand, Kontrolle vor Ort, Fotoprotokoll bei der Übergabe und {1} Jahr Sachmängelhaftung — so prüfen wir importierte, verkaufte und vermietete Autos.",
"Leinformált előélet, ellenőrzött kilométer, helyszíni átvizsgálás, fotós átadás-átvételi jegyzőkönyv és {1} év szavatosság — így ellenőrizzük az importált, eladott és bérelt autókat."
],
"Ako spoločnosť Caradvance GmbH a jej zástupca pre Slovensko, Mr. Job SK s.r.o., spracúvajú osobné údaje: žiadosť o ponuku, prenájom, nákup, predaj auta, preprava…": [
"How Caradvance GmbH and its representative for Slovakia, Mr. Job SK s.r.o., process personal data: requests for offers, rental, purchase, car sale, transport…",
"Wie die Caradvance GmbH und ihr Vertreter für die Slowakei, Mr. Job SK s.r.o., personenbezogene Daten verarbeiten: Angebotsanfrage, Miete, Kauf, Autoverkauf, Transport…",
"Hogyan kezeli a Caradvance GmbH és szlovákiai képviselője, a Mr. Job SK s.r.o. a személyes adatokat: ajánlatkérés, bérlés, vásárlás, autóeladás, szállítás…"
],
