"Tabuľka č. {1} k položke {2} sadzobníka správnych poplatkov — platí pre osobné autá (M{3}), motocykle (L) a ľahké úžitkové vozidlá (N{4}).": [
"Table No. {1} to item {2} of the administrative fee schedule — applies to passenger cars (M{3}), motorcycles (L) and light commercial vehicles (N{4}).",
"Tabelle Nr. {1} zu Posten {2} des Verwaltungsgebührentarifs — gilt für Pkw (M{3}), Motorräder (L) und leichte Nutzfahrzeuge (N{4}).",
"Az igazgatási díjtáblázat {2}. tételéhez tartozó {1}. táblázat — személyautókra (M{3}), motorkerékpárokra (L) és könnyű haszongépjárművekre (N{4}) vonatkozik."
],
