"Poplatok za dovoz a kompletnú administratívu závisí od modelu, ale je transparentný a vopred stanovený. Vďaka veľkej nemeckej ponuke a nemeckým cenám je konečná suma často výhodnejšia než pri podobnom aute zo slovenského trhu.": [
"The fee for import and complete paperwork depends on the model, but it is transparent and fixed in advance. Thanks to the large German supply and German prices, the final amount is often better than for a similar car from the Slovak market.",
"Die Gebühr für Import und Komplettabwicklung hängt vom Modell ab, ist aber transparent und im Voraus festgelegt. Dank des großen deutschen Angebots und der deutschen Preise ist der Endbetrag oft günstiger als bei einem vergleichbaren Auto vom slowakischen Markt.",
"Az import és a teljes ügyintézés díja modellenként eltér, de átlátható és előre rögzített. A nagy német kínálatnak és a német áraknak köszönhetően a végösszeg gyakran kedvezőbb, mint egy hasonló autónál a szlovák piacon."
],
