"Die Preisliste des iX{1} xDrive ohne MwSt. beginnt beim angegebenen Preis, je nach Ausstattung. Privatpersonen und Firmen können ihn über die Caradvance GmbH bei München (Geretsried) bestellen — für ein genaues Angebot kontaktieren Sie uns.",
