"Die Monatsrate ohne MwSt. beginnt ab {1} €/Monat; ein Premium-SUV der Mittelklasse (⟨M1⟩, ⟨M2⟩, ⟨M3⟩) kostet etwa {4}–{5} €, eine Business-Limousine oder ein Kombi etwa {6}–{7} € pro Monat.",
