"Die monatliche Mietrate für den ⟨M1⟩.{1} Tourer beginnt bei {2} €, mit einem Limit von {3}–{4} km/Monat und einer Mietdauer von {5} Monaten. Je nach Version: ID.{6} Tourer Pro ab {7} €/Monat, ID.{8} Tourer Pro S ab {9} €/Monat. Für ein genaues individuelles Angebot kontaktieren Sie uns.",
