"Pre našich zákazníkov: stav vášho auta, očakávaný príchod a splatné sumy.": [
"For our customers: the status of your car, expected arrival and amounts due.",
"Für unsere Kunden: Status Ihres Autos, voraussichtliche Ankunft und fällige Beträge.",
"Ügyfeleinknek: az autód állapota, a várható érkezés és az esedékes összegek."
],
