"Okrem kúpnej ceny preprava, správny poplatok za prihlásenie (podľa výkonu motora a ekologického koeficientu), kontrola originality (podľa cenníka stanice), technická kontrola pri prihlásení a evidenčné číslo. Úradné položky ukáže naša kalkulačka poplatkov za prihlásenie v jednej sume; kompletnú ponuku po položkách vypracujeme my.": [
"Besides the purchase price: transport, the administrative registration fee (based on engine power and the ecological coefficient), the originality check (according to the station's price list), the technical inspection at registration and the number plate. Our registration fee calculator shows the official items as one amount; we prepare the complete itemised offer.",
"Neben dem Kaufpreis: Transport, die Verwaltungsgebühr für die Zulassung (nach Motorleistung und ökologischem Koeffizienten), die Originalitätsprüfung (laut Preisliste der Prüfstelle), die technische Prüfung bei der Zulassung und das Kennzeichen. Unser Zulassungsgebührenrechner zeigt die amtlichen Posten in einer Summe; das vollständige, aufgeschlüsselte Angebot erstellen wir.",
"A vételáron felül: szállítás, a forgalomba helyezés illetéke (a motor teljesítménye és az ökológiai együttható alapján), eredetiségvizsgálat (az állomás árlistája szerint), műszaki vizsga a forgalomba helyezéskor és rendszámtábla. A hatósági tételeket a forgalomba helyezési díj kalkulátorunk egy összegben mutatja; a teljes, tételes ajánlatot mi készítjük el."
],
