"SVG · transparent background · editable strokes · {1} × {2} grid<x0/>Concept preview based on your screenshot. Inclusion is indicated by the column headings; icon colors are decorative.",
"SVG · transparenter Hintergrund · bearbeitbare Linien · {1} × {2} Raster<x0/>Konzeptvorschau auf Basis Ihres Screenshots. Die Einbeziehung ergibt sich aus den Spaltenüberschriften; die Icon-Farben sind dekorativ.",
