"Nový <g0>rad {1}</g0> je dlhší a priestrannejší ako jeho predchodca, dostal ⟨M1⟩ a najnovšie asistenčné systémy. Ideálny je pre firemných aj súkromných zákazníkov — z nemeckej ponuky si môžete objednať z kompletného zoznamu motorov a príplatkovej výbavy.": [
"The new <g0>{1} Series</g0> is longer and roomier than its predecessor and has received ⟨M1⟩ and the latest assistance systems. It is ideal for business and private customers — from the German market you can order from the complete list of engines and optional equipment.",
"Der neue <g0>{1}er</g0> ist länger und geräumiger als sein Vorgänger und hat ⟨M1⟩ sowie die neuesten Assistenzsysteme bekommen. Er ist ideal für Geschäfts- und Privatkunden — aus dem deutschen Angebot können Sie aus der kompletten Liste an Motoren und Sonderausstattungen bestellen.",
"Az új <g0>{1}-es sorozat</g0> hosszabb és tágasabb elődjénél, ⟨M1⟩-t és a legújabb vezetéstámogató rendszereket kapta. Céges és magánügyfeleknek egyaránt ideális — a német kínálatból a motorok és extrák teljes listájából rendelhetsz."
],
"<g0>i{1}</g0> je aj na Slovensku jedným z najžiadanejších prémiových elektrických áut: športový zážitok z jazdy, praktický {2}-litrový kufor a výborná efektivita. Ako firemné auto je vďaka zelenému EČV obzvlášť výhodné.": [
"The <g0>i{1}</g0> is one of the most sought-after premium electric cars in Slovakia too: a sporty driving experience, a practical {2}-litre boot and excellent efficiency. As a company car it is especially advantageous thanks to the green number plate.",
"Der <g0>i{1}</g0> gehört auch in der Slowakei zu den gefragtesten Premium-Elektroautos: sportliches Fahrerlebnis, praktischer {2}-Liter-Kofferraum und hervorragende Effizienz. Als Firmenwagen ist er dank grünem Kennzeichen besonders vorteilhaft.",
"Az <g0>i{1}</g0> Szlovákiában is az egyik legkeresettebb prémium villanyautó: sportos vezetési élmény, praktikus {2} literes csomagtartó és kiváló hatékonyság. Céges autóként a zöld rendszámnak köszönhetően különösen előnyös."
],
"<g0>i{1}</g0> je jednou z najlepších elektrických limuzín vyššej strednej triedy: tichá, priestranná a prináša klasický zážitok z jazdy radu {2}. Ako firemné auto s výhodami zeleného EČV.": [
"The <g0>i{1}</g0> is one of the best electric executive saloons: quiet, spacious and delivering the classic {2} Series driving experience. As a company car, with the benefits of the green number plate.",
"Der <g0>i{1}</g0> ist eine der besten Elektrolimousinen der oberen Mittelklasse: leise, geräumig und mit dem klassischen Fahrerlebnis des {2}ers. Als Firmenwagen mit den Vorteilen des grünen Kennzeichens.",
"Az <g0>i{1}</g0> az egyik legjobb elektromos felső-középkategóriás limuzin: csendes, tágas, és a klasszikus {2}-es vezetési élményt nyújtja. Céges autóként a zöld rendszám előnyeivel."
],
