"The return of the new <g0>⟨M1⟩</g0> (G{2}) is legendary: a {4} hp V{3} plug-in hybrid drive, M xDrive and the practicality of a family estate. At CarAdvance we will order exactly the <g1>⟨M2⟩</g1> you want — as a new car, with factory warranty, with the engine, colour and equipment you want, <g2>from Germany, with turnkey import</g2>. Don't want to buy? The ⟨M3⟩ is also available on <g3>long-term rental</g3> with a single monthly payment.",
