"Všeobecné, orientačné porovnanie — konkrétne podmienky sa líšia podľa poskytovateľa a zmluvy.": [
"A general, indicative comparison — specific terms vary by provider and contract.",
"Ein allgemeiner, unverbindlicher Vergleich — die konkreten Bedingungen variieren je nach Anbieter und Vertrag.",
"Általános, tájékoztató jellegű összehasonlítás — a konkrét feltételek szolgáltatónként és szerződésenként eltérnek."
],
