"<g0>A ⟨M1⟩ {1}-es Limuzin bérlése</g0> havi {2} €-tól indul, {3}–{4} km/hó limittel és {5} hónapos bérleti idővel. Az egyszeri, visszajáró <g1>kaució</g1> {6} €-tól indul, az erősebb változatoknál {7} €. A pontos ár a verziótól, a színtől és a felszereltségi csomagtól függ — az egyes modellek havidíját és elérhetőségét <g2>bérelhető autóink</g2> között találod."
