"<g0>Prenájom ⟨M1⟩</g0> je najjednoduchšia cesta k úplne novému autu: v <g1>dlhodobom prenájme</g1> ho môžete jazdiť od {2} €/mes., s limitom {3}–{4} km/mes. a dobou prenájmu {5} mesiacov. Momentálne si môžete vybrať z {6} áut ⟨M2⟩ ({8} k dispozícii ihneď). Jednorazová vratná <g2>kaucia</g2> od {9} €; servis, daň a letné aj zimné pneumatiky hradíme my. Auto nemusíte vlastniť: na konci prenájmu ho jednoducho vrátite alebo prejdete na nový model.": [
"<g0>Renting the ⟨M1⟩</g0> is the easiest way to a brand-new car: on <g1>long-term rental</g1> you can drive it from {2} €/month, with a limit of {3}–{4} km/month and a rental period of {5} months. You can currently choose from {6} ⟨M2⟩ cars ({8} available immediately). One-off refundable <g2>deposit</g2> from {9} €; we cover servicing, tax and both summer and winter tyres. You don't have to own the car: at the end of the rental you simply return it or switch to a new model.",
"<g0>Den ⟨M1⟩ mieten</g0> ist der einfachste Weg zu einem brandneuen Auto: In der <g1>Langzeitmiete</g1> fahren Sie ihn ab {2} €/Monat, mit einem Limit von {3}–{4} km/Monat und einer Mietdauer von {5} Monaten. Derzeit können Sie aus {6} ⟨M2⟩ Autos wählen ({8} sofort verfügbar). Einmalige rückzahlbare <g2>Kaution</g2> ab {9} €; Service, Steuer sowie Sommer- und Winterreifen übernehmen wir. Sie müssen das Auto nicht besitzen: Am Ende der Miete geben Sie es einfach zurück oder steigen auf ein neues Modell um.",
"<g0>A ⟨M1⟩ bérlése</g0> a legegyszerűbb út egy vadonatúj autóhoz: <g1>tartós bérletben</g1> {2} €/hó-tól vezetheted, {3}–{4} km/hó limittel és {5} hónapos bérleti idővel. Jelenleg {6} ⟨M2⟩ autó közül választhatsz ({8} azonnal elérhető). Egyszeri, visszajáró <g2>kaució</g2> {9} €-tól; a szervizt, az adót, valamint a nyári és téli gumikat mi álljuk. Nem kell az autó tulajdonosának lenned: a bérlet végén egyszerűen visszaadod, vagy új modellre váltasz."
],
"S dlhou kapotou, zrezanou líniou strechy a svalnatou zadnou časťou je X{1} športovejšie než X{2}. Voliteľne svietiaca ľadvinková maska a úzka grafika svetlometov dávajú výraznú tvár; balík M Sport charakter ešte zvýrazňuje. Farby na prenájom: Zafírovo čierna metalíza.": [
"With its long bonnet, cut-off roofline and muscular rear, the X{1} is sportier than the X{2}. The optionally illuminated kidney grille and slim headlight graphics give it a striking face; the M Sport package emphasises its character even more. Colours available for rent: Sapphire Black metallic.",
"Mit langer Motorhaube, abgeschnittener Dachlinie und muskulösem Heck ist der X{1} sportlicher als der X{2}. Die optional leuchtende Niere und die schmale Scheinwerfergrafik geben ihm ein markantes Gesicht; das M Sport Paket betont den Charakter noch mehr. Farben zur Miete: Saphirschwarz Metallic.",
"Hosszú motorháztetővel, levágott tetővonallal és izmos hátsó résszel az X{1} sportosabb, mint az X{2}. Az opcionálisan világító vesehűtőrács és a keskeny fényszóró-grafika karakteres arcot ad; az M Sport csomag még jobban kiemeli a jellegét. Bérelhető színek: Zafír fekete metál."
],
