"<g0>⟨M1⟩</g0> je obľúbenou voľbou v kategórii kombi. V <g1>dlhodobom prenájme</g1> ho môžete jazdiť bez toho, aby ste doň viazali veľkú sumu: platíte jeden <g2>mesačný poplatok</g2>, servis, daň a pneumatiky vybavíme my. To je podstata <g3>dlhodobého prenájmu auta</g3>: predvídateľné náklady, nové auto a žiadne starosti s ďalším predajom.": [
"The <g0>⟨M1⟩</g0> is a popular choice in the estate category. On <g1>long-term rental</g1> you can drive it without tying up a large sum: you pay one <g2>monthly fee</g2>, and we take care of servicing, tax and tyres. That is the essence of <g3>long-term car rental</g3>: predictable costs, a new car and no worries about reselling.",
"Der <g0>⟨M1⟩</g0> ist eine beliebte Wahl in der Kombi-Klasse. In der <g1>Langzeitmiete</g1> fahren Sie ihn, ohne eine große Summe zu binden: Sie zahlen eine <g2>Monatsgebühr</g2>, Service, Steuer und Reifen erledigen wir. Das ist der Kern der <g3>Auto-Langzeitmiete</g3>: planbare Kosten, ein neues Auto und keine Sorgen um den Wiederverkauf.",
"A <g0>⟨M1⟩</g0> népszerű választás a kombik között. <g1>Tartós bérletben</g1> úgy vezetheted, hogy nem kötsz le benne nagy összeget: egy <g2>havidíjat</g2> fizetsz, a szervizt, az adót és a gumikat mi intézzük. Ez a <g3>tartós autóbérlet</g3> lényege: kiszámítható költségek, új autó és nincs gond a továbbértékesítéssel."
],
