"<g0>Prenájom ⟨M1⟩</g0> je najjednoduchšia cesta k úplne novému autu: v <g1>dlhodobom prenájme</g1> ho môžete jazdiť od {1} €/mes., s limitom {2}–{3} km/mes. a dobou prenájmu {4} mesiacov. Momentálne si môžete vybrať z {5} áut ⟨M2⟩ ({6} k dispozícii ihneď), vo verziách {7} T-GDI {8}WD Trend, {9} T-GDI {10}WD N Line, {11} T-GDI {12}WD N Line X, {13} T-GDI {14}WD Prime. Jednorazová vratná <g2>kaucia</g2> od {15} €; servis, daň a letné aj zimné pneumatiky hradíme my. Auto nemusíte vlastniť: na konci prenájmu ho jednoducho vrátite alebo prejdete na nový model.": [
"<g0>Renting the ⟨M1⟩</g0> is the easiest way to a brand-new car: on <g1>long-term rental</g1> you can drive it from {1} €/month, with a limit of {2}–{3} km/month and a rental period of {4} months. You can currently choose from {5} ⟨M2⟩ cars ({6} available immediately), in the versions {7} T-GDI {8}WD Trend, {9} T-GDI {10}WD N Line, {11} T-GDI {12}WD N Line X, {13} T-GDI {14}WD Prime. One-off refundable <g2>deposit</g2> from {15} €; we cover servicing, tax and both summer and winter tyres. You don't have to own the car: at the end of the rental you simply return it or switch to a new model.",
"<g0>Den ⟨M1⟩ mieten</g0> ist der einfachste Weg zu einem brandneuen Auto: In der <g1>Langzeitmiete</g1> fahren Sie ihn ab {1} €/Monat, mit einem Limit von {2}–{3} km/Monat und einer Mietdauer von {4} Monaten. Derzeit können Sie aus {5} ⟨M2⟩ Autos wählen ({6} sofort verfügbar), in den Versionen {7} T-GDI {8}WD Trend, {9} T-GDI {10}WD N Line, {11} T-GDI {12}WD N Line X, {13} T-GDI {14}WD Prime. Einmalige rückzahlbare <g2>Kaution</g2> ab {15} €; Service, Steuer sowie Sommer- und Winterreifen übernehmen wir. Sie müssen das Auto nicht besitzen: Am Ende der Miete geben Sie es einfach zurück oder steigen auf ein neues Modell um.",
"<g0>A ⟨M1⟩ bérlése</g0> a legegyszerűbb út egy vadonatúj autóhoz: <g1>tartós bérletben</g1> {1} €/hó-tól vezetheted, {2}–{3} km/hó limittel és {4} hónapos bérleti idővel. Jelenleg {5} ⟨M2⟩ autó közül választhatsz ({6} azonnal elérhető), {7} T-GDI {8}WD Trend, {9} T-GDI {10}WD N Line, {11} T-GDI {12}WD N Line X és {13} T-GDI {14}WD Prime változatban. Egyszeri, visszajáró <g2>kaució</g2> {15} €-tól; a szervizt, az adót, valamint a nyári és téli gumikat mi álljuk. Nem kell az autó tulajdonosának lenned: a bérlet végén egyszerűen visszaadod, vagy új modellre váltasz."
],
"Na prenájom: {1} T-GDI {2}WD Trend (benzín), {3} T-GDI {4}WD N Line (benzín), {5} T-GDI {6}WD N Line X (benzín), {7} T-GDI {8}WD Prime (benzín).": [
"For rent: {1} T-GDI {2}WD Trend (petrol), {3} T-GDI {4}WD N Line (petrol), {5} T-GDI {6}WD N Line X (petrol), {7} T-GDI {8}WD Prime (petrol).",
"Zur Miete: {1} T-GDI {2}WD Trend (Benzin), {3} T-GDI {4}WD N Line (Benzin), {5} T-GDI {6}WD N Line X (Benzin), {7} T-GDI {8}WD Prime (Benzin).",
"Bérelhető: {1} T-GDI {2}WD Trend (benzin), {3} T-GDI {4}WD N Line (benzin), {5} T-GDI {6}WD N Line X (benzin), {7} T-GDI {8}WD Prime (benzin)."
],
"„Parametrická“ maska chladiča so skrytými LED svetlami pre denné svietenie, ostré línie a športové nárazníky verzie N Line robia z modelu Tucson jedinečné auto. Farby na prenájom: Ecotronic sivá, Žiarivá červená, Tieňovo sivá.": [
"The “parametric” grille with hidden LED daytime running lights, sharp lines and the sporty N Line bumpers make the Tucson a unique car. Colours available for rent: Ecotronic Grey, Engine Red, Shadow Grey.",
"Der „parametrische“ Kühlergrill mit versteckten LED-Tagfahrlichtern, scharfe Linien und die sportlichen Stoßfänger der N Line machen den Tucson zu einem einzigartigen Auto. Farben zur Miete: Ecotronic Grey, Engine Red, Shadow Grey.",
"Az „parametrikus” hűtőrács rejtett LED nappali menetfényekkel, az éles vonalak és az N Line sportos lökhárítói egyedivé teszik a Tucsont. Bérelhető színek: Ecotronic szürke, Ragyogó piros, Árnyékszürke."
],
"Momentálne si môžete vybrať z {1} verzií: <g0>{2} T-GDI {3}WD Trend</g0> — benzín, od, od {4} €/mes.; <g1>{5} T-GDI {6}WD N Line</g1> — benzín, od, od {7} €/mes.; <g2>{8} T-GDI {9}WD N Line X</g2> — benzín, od, od {10} €/mes.; <g3>{11} T-GDI {12}WD Prime</g3> — benzín, od, od {13} €/mes.": [
"You can currently choose from {1} versions: <g0>{2} T-GDI {3}WD Trend</g0> — petrol, from {4} €/month; <g1>{5} T-GDI {6}WD N Line</g1> — petrol, from {7} €/month; <g2>{8} T-GDI {9}WD N Line X</g2> — petrol, from {10} €/month; <g3>{11} T-GDI {12}WD Prime</g3> — petrol, from {13} €/month.",
"Derzeit können Sie aus {1} Versionen wählen: <g0>{2} T-GDI {3}WD Trend</g0> — Benzin, ab {4} €/Monat; <g1>{5} T-GDI {6}WD N Line</g1> — Benzin, ab {7} €/Monat; <g2>{8} T-GDI {9}WD N Line X</g2> — Benzin, ab {10} €/Monat; <g3>{11} T-GDI {12}WD Prime</g3> — Benzin, ab {13} €/Monat.",
"Jelenleg {1} változat közül választhatsz: <g0>{2} T-GDI {3}WD Trend</g0> — benzin, {4} €/hó-tól; <g1>{5} T-GDI {6}WD N Line</g1> — benzin, {7} €/hó-tól; <g2>{8} T-GDI {9}WD N Line X</g2> — benzin, {10} €/hó-tól; <g3>{11} T-GDI {12}WD Prime</g3> — benzin, {13} €/hó-tól."
],
