"Kontakt po slovensky, anglicky alebo nemecky": [
"Contact in Slovak, English or German",
"Kontakt auf Slowakisch, Englisch oder Deutsch",
"Kapcsolattartás szlovákul, angolul vagy németül"
],
"Jedna kontaktná osoba, po slovensky, anglicky alebo nemecky — rýchla ponuka a odovzdanie auta.": [
"One contact person, in Slovak, English or German — a quick offer and handover of the car.",
"Ein Ansprechpartner, auf Slowakisch, Englisch oder Deutsch — schnelles Angebot und Übergabe des Autos.",
"Egy kapcsolattartó, szlovákul, angolul vagy németül — gyors ajánlat és autóátadás."
],
"Dlhodobý prenájom ponúkame predovšetkým firmám – platiteľom DPH; mesačný poplatok je uvedený bez DPH. Ste súkromná osoba alebo podnikateľ bez IČ DPH? Zavolajte nám – nájdeme správne riešenie aj pre vás. <g0>Lízing pre súkromné osoby</g0> často znamená dlhú viazanosť a akontáciu; pri dlhodobom prenájme stačí vratná kaucia.": [
"We offer long-term rental primarily to companies registered for VAT; the monthly fee is shown excl. VAT. Are you a private individual or a business without a VAT ID? Call us – we will find the right solution for you too. <g0>Leasing for private individuals</g0> often means a long commitment and a down payment; with long-term rental a refundable deposit is enough.",
"Die Langzeitmiete bieten wir vor allem umsatzsteuerpflichtigen Firmen an; die Monatsgebühr ist ohne MwSt. angegeben. Sie sind Privatperson oder Unternehmer ohne USt-IdNr.? Rufen Sie uns an – wir finden auch für Sie die richtige Lösung. <g0>Leasing für Privatpersonen</g0> bedeutet oft lange Bindung und Anzahlung; bei der Langzeitmiete genügt eine rückzahlbare Kaution.",
"A tartós bérletet elsősorban áfaköteles cégeknek kínáljuk; a havidíj áfa nélkül értendő. Magánszemély vagy közösségi adószám nélküli vállalkozó vagy? Hívj minket – neked is megtaláljuk a megfelelő megoldást. A <g0>magánszemélyeknek szóló lízing</g0> gyakran hosszú kötöttséggel és önerővel jár; tartós bérletnél elég a visszajáró kaució."
],
"Mesačný poplatok zahŕňa servis, daň, poistenie aj pneumatiky; vy platíte len nabíjanie, ktoré pri nabíjaní doma zvyčajne stojí zlomok ceny benzínu. O možnostiach financovania elektromobilov sme písali v článku lízing elektromobilu a dotácie.": [
"The monthly fee covers servicing, tax, insurance and tyres; you only pay for charging, which when done at home usually costs a fraction of the price of petrol. We wrote about financing options for electric cars in our article on electric car leasing and subsidies.",
"Die Monatsgebühr umfasst Service, Steuer, Versicherung und Reifen; Sie zahlen nur das Laden, das zu Hause meist nur einen Bruchteil des Benzinpreises kostet. Über Finanzierungsmöglichkeiten für Elektroautos haben wir im Artikel E-Auto-Leasing und Förderungen geschrieben.",
"A havidíj tartalmazza a szervizt, az adót, a biztosítást és a gumikat; te csak a töltést fizeted, ami otthoni töltésnél általában a benzinár töredéke. A villanyautók finanszírozási lehetőségeiről a villanyautó-lízingről és támogatásokról szóló cikkünkben írtunk."
],
"<g0><g1>⟨M1⟩</g1><g2>od {1} €/mes.</g2></g0><g3><g4>⟨M2⟩.{2} Tourer</g4><g5>od {3} €/mes.</g5></g3><g6><g7>⟨M3⟩</g7><g8>od {4} €/mes.</g8></g6><g9><g10>⟨M4⟩</g10><g11>od {6} €/mes.</g11></g9><g12><g13>⟨M5⟩</g13><g14>od {8} €/mes.</g14></g12><g15><g16>⟨M6⟩</g16><g17>od {10} €/mes.</g17></g15>": [
"<g0><g1>⟨M1⟩</g1><g2>from {1} €/month</g2></g0><g3><g4>⟨M2⟩.{2} Tourer</g4><g5>from {3} €/month</g5></g3><g6><g7>⟨M3⟩</g7><g8>from {4} €/month</g8></g6><g9><g10>⟨M4⟩</g10><g11>from {6} €/month</g11></g9><g12><g13>⟨M5⟩</g13><g14>from {8} €/month</g14></g12><g15><g16>⟨M6⟩</g16><g17>from {10} €/month</g17></g15>",
"<g0><g1>⟨M1⟩</g1><g2>ab {1} €/Monat</g2></g0><g3><g4>⟨M2⟩.{2} Tourer</g4><g5>ab {3} €/Monat</g5></g3><g6><g7>⟨M3⟩</g7><g8>ab {4} €/Monat</g8></g6><g9><g10>⟨M4⟩</g10><g11>ab {6} €/Monat</g11></g9><g12><g13>⟨M5⟩</g13><g14>ab {8} €/Monat</g14></g12><g15><g16>⟨M6⟩</g16><g17>ab {10} €/Monat</g17></g15>",
"<g0><g1>⟨M1⟩</g1><g2>{1} €/hó-tól</g2></g0><g3><g4>⟨M2⟩.{2} Tourer</g4><g5>{3} €/hó-tól</g5></g3><g6><g7>⟨M3⟩</g7><g8>{4} €/hó-tól</g8></g6><g9><g10>⟨M4⟩</g10><g11>{6} €/hó-tól</g11></g9><g12><g13>⟨M5⟩</g13><g14>{8} €/hó-tól</g14></g12><g15><g16>⟨M6⟩</g16><g17>{10} €/hó-tól</g17></g15>"
],
