"Kliknite na značku: na stránke autá na prenájom uvidíte vyfiltrované modely s fotkami, cenou pre firmy (bez DPH) a možnosťou požiadať o ponuku.": [
"Click on a brand: on the cars-for-rent page you will see the filtered models with photos, the price for companies (excl. VAT) and the option to request an offer.",
"Klicken Sie auf eine Marke: Auf der Seite Mietautos sehen Sie die gefilterten Modelle mit Fotos, dem Preis für Firmen (ohne MwSt.) und der Möglichkeit, ein Angebot anzufordern.",
"Kattints egy márkára: a bérelhető autók oldalán a szűrt modelleket látod fotókkal, céges árral (áfa nélkül) és ajánlatkérési lehetőséggel."
],
