"Čisté ceny „od“, pri dobe aspoň {1} mesiacov, s limitom {2}–{3} km mesačne (podľa auta); cena v eurách závisí od denného kurzu eura, presný poplatok od verzie, farby a balíka.": [
"Net “from” prices, for a term of at least {1} months, with a limit of {2}–{3} km per month (depending on the car); the price depends on the daily euro exchange rate, and the exact fee on the version, colour and package.",
"Nettopreise „ab“, bei einer Laufzeit von mindestens {1} Monaten, mit einem Limit von {2}–{3} km pro Monat (je nach Auto); der Preis hängt vom tagesaktuellen Eurokurs ab, die genaue Gebühr von Version, Farbe und Paket.",
"Nettó „-tól” árak, legalább {1} hónapos időtartamra, havi {2}–{3} km limittel (autótól függően); az ár a napi euróárfolyamtól, a pontos díj a verziótól, a színtől és a csomagtól függ."
],
