"Dlhá kapota, kabína posunutá dozadu, krátke previsy a športové proporcie — Trieda C prináša dizajnový jazyk Triedy S do strednej triedy. Farby na prenájom: Obsidiánová čierna metalíza, Polárna biela uni.": [
"Long bonnet, cabin set back, short overhangs and sporty proportions — the C-Class brings the S-Class design language to the mid-size class. Colours available for rent: Obsidian Black metallic, Polar White.",
"Lange Motorhaube, nach hinten versetzte Kabine, kurze Überhänge und sportliche Proportionen — die C-Klasse bringt die Designsprache der S-Klasse in die Mittelklasse. Farben zur Miete: Obsidianschwarz Metallic, Polarweiß uni.",
"Hosszú motorháztető, hátrébb húzott utastér, rövid túlnyúlások és sportos arányok — a C-osztály az S-osztály formanyelvét hozza a középkategóriába. Bérelhető színek: Obszidián fekete metál, Polárfehér uni."
],
"Plochá, napnutá karoséria, bezrámové okná dverí, maska chladiča so svietiacim hviezdicovým vzorom a vzadu hviezdicové svetlá — nové CLA otvára novú dizajnovú éru Mercedesu. Farby na prenájom: Polárna biela uni, Polnočná čierna uni.": [
"A flat, taut body, frameless door windows, a grille with an illuminated star pattern and star-shaped tail lights — the new CLA opens a new design era for Mercedes. Colours available for rent: Polar White, Night Black.",
"Flache, straffe Karosserie, rahmenlose Türscheiben, ein Kühlergrill mit leuchtendem Sternmuster und Sternrückleuchten — der neue CLA eröffnet eine neue Design-Ära bei Mercedes. Farben zur Miete: Polarweiß uni, Nachtschwarz uni.",
"Lapos, feszes karosszéria, keret nélküli ajtóablakok, világító csillagmintás hűtőrács és csillag alakú hátsó lámpák — az új CLA a Mercedes új formatervezési korszakát nyitja meg. Bérelhető színek: Polárfehér uni, Éjfekete uni."
],
"<g0>Prenájom ⟨M1⟩</g0> začína na {1} € ({2} €) mesačne, s limitom {3}–{4} km/mes. a dobou prenájmu {5} mesiacov. Jednorazová vratná <g1>kaucia</g1> začína na {6} €. Presná cena závisí od verzie, farby a balíka výbavy — mesačnú splátku a dostupnosť každého modelu nájdete medzi našimi <g2>autami na prenájom</g2>.": [
"<g0>Renting the ⟨M1⟩</g0> starts at {1} € ({2} €) per month, with a limit of {3}–{4} km/month and a rental period of {5} months. The one-off refundable <g1>deposit</g1> starts at {6} €. The exact price depends on the version, colour and equipment package — you will find the monthly fee and availability of each model among our <g2>cars for rent</g2>.",
"<g0>Die Miete des ⟨M1⟩</g0> beginnt bei {1} € ({2} €) monatlich, mit einem Limit von {3}–{4} km/Monat und einer Mietdauer von {5} Monaten. Die einmalige rückzahlbare <g1>Kaution</g1> beginnt bei {6} €. Der genaue Preis hängt von Version, Farbe und Ausstattungspaket ab — Monatsrate und Verfügbarkeit jedes Modells finden Sie unter unseren <g2>Mietautos</g2>.",
"<g0>A ⟨M1⟩ bérlése</g0> havi {1} €-tól ({2} €) indul, {3}–{4} km/hó limittel és {5} hónapos bérleti idővel. Az egyszeri, visszajáró <g1>kaució</g1> {6} €-tól indul. A pontos ár a verziótól, a színtől és a felszereltségi csomagtól függ — az egyes modellek havidíját és elérhetőségét <g2>bérelhető autóink</g2> között találod."
],
"<g0>Limuzína</g0><g1>Benzín · Diesel</g1><g2>Automat</g2><g3>{1}–{2} km/mes.</g3><g4>Úplne nové · {3} km</g4>": [
"<g0>Saloon</g0><g1>Petrol · Diesel</g1><g2>Automatic</g2><g3>{1}–{2} km/month</g3><g4>Brand new · {3} km</g4>",
"<g0>Limousine</g0><g1>Benzin · Diesel</g1><g2>Automatik</g2><g3>{1}–{2} km/Monat</g3><g4>Brandneu · {3} km</g4>",
"<g0>Limuzin</g0><g1>Benzin · Dízel</g1><g2>Automata</g2><g3>{1}–{2} km/hó</g3><g4>Vadonatúj · {3} km</g4>"
],
"<g0>Prenájom ⟨M1⟩ trieda E Limuzína</g0> je najjednoduchšia cesta k úplne novému autu: v <g1>dlhodobom prenájme</g1> ho môžete jazdiť od {1} €/mes., s limitom {2}–{3} km/mes. a dobou prenájmu {4} mesiacov. Momentálne si môžete vybrať z {5} áut ⟨M2⟩ trieda E Limuzína ({6} k dispozícii ihneď), vo verziách E {7}, E {8} d. Jednorazová vratná <g2>kaucia</g2> od {9} €; servis, daň a letné aj zimné pneumatiky hradíme my. Auto nemusíte vlastniť: na konci prenájmu ho jednoducho vrátite alebo prejdete na nový model.": [
"<g0>Renting the ⟨M1⟩ E-Class Saloon</g0> is the easiest way to a brand-new car: on <g1>long-term rental</g1> you can drive it from {1} €/month, with a limit of {2}–{3} km/month and a rental period of {4} months. You can currently choose from {5} ⟨M2⟩ E-Class Saloon cars ({6} available immediately), in the versions E {7}, E {8} d. One-off refundable <g2>deposit</g2> from {9} €; we cover servicing, tax and both summer and winter tyres. You don't have to own the car: at the end of the rental you simply return it or switch to a new model.",
"<g0>Die ⟨M1⟩ E-Klasse Limousine mieten</g0> ist der einfachste Weg zu einem brandneuen Auto: In der <g1>Langzeitmiete</g1> fahren Sie sie ab {1} €/Monat, mit einem Limit von {2}–{3} km/Monat und einer Mietdauer von {4} Monaten. Derzeit können Sie aus {5} ⟨M2⟩ E-Klasse Limousinen wählen ({6} sofort verfügbar), in den Versionen E {7}, E {8} d. Einmalige rückzahlbare <g2>Kaution</g2> ab {9} €; Service, Steuer sowie Sommer- und Winterreifen übernehmen wir. Sie müssen das Auto nicht besitzen: Am Ende der Miete geben Sie es einfach zurück oder steigen auf ein neues Modell um.",
"<g0>A ⟨M1⟩ E-osztály Limuzin bérlése</g0> a legegyszerűbb út egy vadonatúj autóhoz: <g1>tartós bérletben</g1> {1} €/hó-tól vezetheted, {2}–{3} km/hó limittel és {4} hónapos bérleti idővel. Jelenleg {5} ⟨M2⟩ E-osztály Limuzin közül választhatsz ({6} azonnal elérhető), E {7} és E {8} d változatban. Egyszeri, visszajáró <g2>kaució</g2> {9} €-tól; a szervizt, az adót, valamint a nyári és téli gumikat mi álljuk. Nem kell az autó tulajdonosának lenned: a bérlet végén egyszerűen visszaadod, vagy új modellre váltasz."
],
"Nová Trieda E dostala masku chladiča integrovanú do čierneho panelu, zadné svetlá s motívom hviezdy a čistú, elegantnú bočnú líniu. Farby na prenájom: Obsidiánová čierna metalíza, Polárna biela uni.": [
"The new E-Class has a grille integrated into a black panel, star-motif tail lights and a clean, elegant side line. Colours available for rent: Obsidian Black metallic, Polar White.",
"Die neue E-Klasse hat einen in eine schwarze Blende integrierten Kühlergrill, Rückleuchten mit Sternmotiv und eine klare, elegante Seitenlinie. Farben zur Miete: Obsidianschwarz Metallic, Polarweiß uni.",
"Az új E-osztály fekete panelbe integrált hűtőrácsot, csillagmotívumos hátsó lámpákat és tiszta, elegáns oldalvonalat kapott. Bérelhető színek: Obszidián fekete metál, Polárfehér uni."
],
