"Derzeit können Sie aus {1} Versionen wählen: <g0>{2} d {3}MATIC</g0> — Sechszylinder-Diesel, ab {4} €/Monat; <g1>{5}MATIC</g1> — Sechszylinder-Benziner, ab {6} €/Monat; <g2>{7} d {8}MATIC</g2> — Sechszylinder-Diesel, hohes Drehmoment, ab {9} €/Monat.",
