"Výška: údaj výrobcu bez strešného nosiča. Šírka: s vyklopenými zrkadlami. Na pohodlné vystupovanie treba aspoň ~{1} cm na každej strane. Podzemné garáže majú zvyčajne vjazdovú výšku {2}–{3} m – vždy si pozrite tabuľu pri vjazde.": [
"Height: manufacturer's figure without roof rack. Width: with mirrors folded out. For comfortable getting out you need at least ~{1} cm on each side. Underground garages usually have an entrance height of {2}–{3} m – always check the sign at the entrance.",
"Höhe: Herstellerangabe ohne Dachträger. Breite: mit ausgeklappten Spiegeln. Zum bequemen Aussteigen braucht man mindestens ~{1} cm auf jeder Seite. Tiefgaragen haben meist eine Einfahrtshöhe von {2}–{3} m – achten Sie immer auf das Schild an der Einfahrt.",
"Magasság: gyári adat tetőcsomagtartó nélkül. Szélesség: kihajtott tükrökkel. A kényelmes kiszálláshoz mindkét oldalon legalább ~{1} cm kell. A mélygarázsok behajtási magassága általában {2}–{3} m – mindig nézd meg a táblát a bejáratnál."
],
