"Derzeit können Sie aus {1} Versionen wählen: <g0>{2} eTSI DSG</g0> — Mild-Hybrid, Automatik · Ausstattung: Energy, R-Line, ab {3} €/Monat; <g1>{4} TSI {5}MOTION DSG</g1> — kräftiger Benziner, Allradantrieb · Ausstattung: R-Line, Style, ab {6} €/Monat.",
