"<g0>Prenájom ⟨M1⟩</g0> je najjednoduchšia cesta k úplne novému autu: v <g1>dlhodobom prenájme</g1> ho môžete jazdiť od {1} €/mes., s limitom {2}–{3} km/mes. a dobou prenájmu {4} mesiacov. Momentálne si môžete vybrať z {5} áut ⟨M2⟩ ({6} k dispozícii ihneď), vo verziách {7} eTSI DSG, {8} TDI DSG, {9} eHybrid DSG. Jednorazová vratná <g2>kaucia</g2> od {10} €; servis, daň a letné aj zimné pneumatiky hradíme my. Auto nemusíte vlastniť: na konci prenájmu ho jednoducho vrátite alebo prejdete na nový model.": [
"<g0>Renting the ⟨M1⟩</g0> is the easiest way to a brand-new car: on <g1>long-term rental</g1> you can drive it from {1} €/month, with a limit of {2}–{3} km/month and a rental period of {4} months. You can currently choose from {5} ⟨M2⟩ cars ({6} available immediately), in the versions {7} eTSI DSG, {8} TDI DSG, {9} eHybrid DSG. One-off refundable <g2>deposit</g2> from {10} €; we cover servicing, tax and both summer and winter tyres. You don't have to own the car: at the end of the rental you simply return it or switch to a new model.",
"<g0>Den ⟨M1⟩ mieten</g0> ist der einfachste Weg zu einem brandneuen Auto: In der <g1>Langzeitmiete</g1> fahren Sie ihn ab {1} €/Monat, mit einem Limit von {2}–{3} km/Monat und einer Mietdauer von {4} Monaten. Derzeit können Sie aus {5} ⟨M2⟩ Autos wählen ({6} sofort verfügbar), in den Versionen {7} eTSI DSG, {8} TDI DSG, {9} eHybrid DSG. Einmalige rückzahlbare <g2>Kaution</g2> ab {10} €; Service, Steuer sowie Sommer- und Winterreifen übernehmen wir. Sie müssen das Auto nicht besitzen: Am Ende der Miete geben Sie es einfach zurück oder steigen auf ein neues Modell um.",
"<g0>A ⟨M1⟩ bérlése</g0> a legegyszerűbb út egy vadonatúj autóhoz: <g1>tartós bérletben</g1> {1} €/hó-tól vezetheted, {2}–{3} km/hó limittel és {4} hónapos bérleti idővel. Jelenleg {5} ⟨M2⟩ autó közül választhatsz ({6} azonnal elérhető), {7} eTSI DSG, {8} TDI DSG és {9} eHybrid DSG változatban. Egyszeri, visszajáró <g2>kaució</g2> {10} €-tól; a szervizt, az adót, valamint a nyári és téli gumikat mi álljuk. Nem kell az autó tulajdonosának lenned: a bérlet végén egyszerűen visszaadod, vagy új modellre váltasz."
],
