"Modernizovaný T-Cross dostal nové nárazníky, LED svetlomety IQ. LIGHT a zadný stmavený svetelný pás cez celú šírku vozidla. Farby na prenájom: Kráľovská červená metalíza, Ascot sivá, Dymovo sivá metalíza, Čisto modrá metalíza.": [
"The updated T-Cross has new bumpers, IQ.LIGHT LED headlights and a darkened full-width light strip at the rear. Colours available for rent: Kings Red metallic, Ascot Grey, Smoke Grey metallic, Clear Blue metallic.",
"Der modernisierte T-Cross hat neue Stoßfänger, IQ.LIGHT LED-Scheinwerfer und ein abgedunkeltes, durchgehendes Lichtband am Heck. Farben zur Miete: Kings Red Metallic, Ascotgrau, Smokegrau Metallic, Clear Blue Metallic.",
"A megújult T-Cross új lökhárítókat, IQ.LIGHT LED fényszórókat és hátul teljes szélességű, sötétített fénycsíkot kapott. Bérelhető színek: Királyi piros metál, Ascot szürke, Füstszürke metál, Tiszta kék metál."
],
