"Nový T-Roc dostal svetelný pás a svietiace logo, úzke LED svetlomety a kupéovitejšiu líniu strechy — športové, a predsa praktické kompaktné SUV. Farby na prenájom: Wolf sivá metalíza, Grenadill čierna metalíza, Čisto biela uni, Pyritovo strieborná metalíza.": [
"The new T-Roc has a light strip and illuminated logo, slim LED headlights and a more coupé-like roofline — a sporty yet practical compact SUV. Colours available for rent: Wolf Grey metallic, Grenadilla Black metallic, Pure White, Pyrite Silver metallic.",
"Der neue T-Roc hat ein Lichtband und ein leuchtendes Logo, schmale LED-Scheinwerfer und eine coupéhaftere Dachlinie — ein sportliches und dennoch praktisches Kompakt-SUV. Farben zur Miete: Wolfgrau Metallic, Grenadillschwarz Metallic, Reinweiß uni, Pyritsilber Metallic.",
"Az új T-Roc fénycsíkot és világító logót, keskeny LED fényszórókat és kupésabb tetővonalat kapott — sportos, mégis praktikus kompakt SUV. Bérelhető színek: Wolf szürke metál, Grenadill fekete metál, Tiszta fehér uni, Pirit ezüst metál."
],
